const o=compileVueSfc(`<template><view @click=\"emit('go',1)\">x</view></template>
<script setup lang=ts>const emit=defineEmits()</script>`,{px2rpx:true,rpxRatio:2},{file:'t.vue'})
console.log(o.js.match(/emit:\\s*\\w+/)?.[0]) })  // → emit: undefined"

